CREATE TABLE public.network_profiles (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, cities text[] NOT NULL DEFAULT '{}', zip_codes text[] NOT NULL DEFAULT '{}', primary_market text, specialties text[] NOT NULL DEFAULT '{}', credentials text, notify_area boolean NOT NULL DEFAULT true, notify_interest boolean NOT NULL DEFAULT true, notify_message boolean NOT NULL DEFAULT true, notify_connection boolean NOT NULL DEFAULT true, notify_status boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.network_profiles TO authenticated; GRANT ALL ON public.network_profiles TO service_role; ALTER TABLE public.network_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY network_profile_self ON public.network_profiles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.network_referrals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, referral_source text NOT NULL DEFAULT 'realtor_network' CHECK(referral_source='realtor_network'), referral_type text NOT NULL CHECK(referral_type IN ('Buyer','Seller','Buyer & Seller','Commercial','Land','Rental','Other')), state text NOT NULL CHECK(public.is_valid_us_state(state)), city text NOT NULL CHECK(length(trim(city))>0), county text, zip text, property_type text NOT NULL CHECK(length(trim(property_type))>0), min_price numeric NOT NULL CHECK(min_price>=0), max_price numeric NOT NULL CHECK(max_price>=min_price), description text NOT NULL CHECK(length(trim(description)) BETWEEN 1 AND 4000), preferred_experience text NOT NULL CHECK(length(trim(preferred_experience))>0), fee_offered text, urgency text NOT NULL CHECK(urgency IN ('Immediate','Within 30 Days','30–90 Days','Flexible')), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','interested','connected','closed','cancelled','expired')), selected_realtor_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, hidden boolean NOT NULL DEFAULT false, moderation_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(nullif(trim(county),'') IS NOT NULL OR coalesce(zip ~ '^[0-9]{5}$',false)));
GRANT SELECT ON public.network_referrals TO authenticated; GRANT ALL ON public.network_referrals TO service_role; ALTER TABLE public.network_referrals ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.network_responses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), referral_id uuid NOT NULL REFERENCES public.network_referrals(id) ON DELETE CASCADE, realtor_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, interested boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(referral_id,realtor_id));
GRANT SELECT ON public.network_responses TO authenticated; GRANT ALL ON public.network_responses TO service_role; ALTER TABLE public.network_responses ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.network_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), response_id uuid NOT NULL REFERENCES public.network_responses(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, body text NOT NULL CHECK(length(trim(body)) BETWEEN 1 AND 4000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.network_messages TO authenticated; GRANT ALL ON public.network_messages TO service_role; ALTER TABLE public.network_messages ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.network_agreements(referral_id uuid PRIMARY KEY REFERENCES public.network_referrals(id) ON DELETE CASCADE, recorded_by uuid NOT NULL REFERENCES public.profiles(id), reference text NOT NULL CHECK(length(trim(reference))>0), brokerage_approved boolean NOT NULL CHECK(brokerage_approved), licensing_confirmed boolean NOT NULL CHECK(licensing_confirmed), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.network_agreements TO authenticated; GRANT ALL ON public.network_agreements TO service_role; ALTER TABLE public.network_agreements ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.network_activity(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), referral_id uuid NOT NULL REFERENCES public.network_referrals(id) ON DELETE CASCADE, actor_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, event text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.network_activity TO authenticated; GRANT ALL ON public.network_activity TO service_role; ALTER TABLE public.network_activity ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.network_notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, referral_id uuid REFERENCES public.network_referrals(id) ON DELETE CASCADE, event text NOT NULL, title text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.network_notifications TO authenticated; GRANT ALL ON public.network_notifications TO service_role; ALTER TABLE public.network_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY network_notifications_self ON public.network_notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.network_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), referral_id uuid NOT NULL REFERENCES public.network_referrals(id) ON DELETE CASCADE, reporter_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, reported_user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, reason text NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 2000), resolved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.network_reports TO authenticated; GRANT ALL ON public.network_reports TO service_role; ALTER TABLE public.network_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY network_reports_read ON public.network_reports FOR SELECT TO authenticated USING(reporter_id=auth.uid() OR public.is_admin());
CREATE INDEX network_referrals_market ON public.network_referrals(state,city,status); CREATE INDEX network_messages_thread ON public.network_messages(response_id,created_at); CREATE INDEX network_notifications_user ON public.network_notifications(user_id,created_at);
CREATE FUNCTION public.network_eligible(p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_user AND role='realtor' AND nullif(trim(license_number),'') IS NOT NULL); $$;
CREATE FUNCTION public.network_can_read(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_admin() OR (public.network_eligible(auth.uid()) AND EXISTS(SELECT 1 FROM public.network_referrals r WHERE r.id=p_id AND (r.owner_id=auth.uid() OR (NOT r.hidden AND (r.status IN ('open','interested') OR r.selected_realtor_id=auth.uid() OR EXISTS(SELECT 1 FROM public.network_responses x WHERE x.referral_id=r.id AND x.realtor_id=auth.uid())))))); $$;
CREATE FUNCTION public.network_thread_access(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.network_eligible(auth.uid()) AND EXISTS(SELECT 1 FROM public.network_responses x JOIN public.network_referrals r ON r.id=x.referral_id WHERE x.id=p_id AND NOT r.hidden AND (x.realtor_id=auth.uid() OR r.owner_id=auth.uid())); $$;
CREATE POLICY network_referrals_read ON public.network_referrals FOR SELECT TO authenticated USING(public.network_can_read(id)); CREATE POLICY network_responses_read ON public.network_responses FOR SELECT TO authenticated USING(public.network_thread_access(id) OR public.is_admin()); CREATE POLICY network_messages_private ON public.network_messages FOR SELECT TO authenticated USING(public.network_thread_access(response_id)); CREATE POLICY network_agreements_parties ON public.network_agreements FOR SELECT TO authenticated USING(public.network_eligible(auth.uid()) AND EXISTS(SELECT 1 FROM public.network_referrals r WHERE r.id=referral_id AND NOT r.hidden AND (r.owner_id=auth.uid() OR r.selected_realtor_id=auth.uid()))); CREATE POLICY network_activity_read ON public.network_activity FOR SELECT TO authenticated USING(public.network_can_read(referral_id));
CREATE FUNCTION public.network_area_match(p_user uuid,p_state text,p_city text,p_county text,p_zip text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles p LEFT JOIN public.network_profiles n ON n.user_id=p.id WHERE p.id=p_user AND public.network_eligible(p.id) AND (p_state=ANY(p.markets) OR p.license_state=p_state) AND (NOT EXISTS(SELECT 1 FROM unnest(p.counties) c WHERE c LIKE p_state||':%') OR p_state||':'||p_county=ANY(p.counties) OR (p_county IS NULL AND p_zip IS NOT NULL AND p_zip=ANY(n.zip_codes))) AND (coalesce(cardinality(n.cities),0)=0 OR EXISTS(SELECT 1 FROM unnest(n.cities) c WHERE lower(c)=lower(p_state||':'||p_city))) AND (coalesce(cardinality(n.zip_codes),0)=0 OR p_zip=ANY(n.zip_codes))); $$;
CREATE FUNCTION public.network_notify(p_user uuid,p_ref uuid,p_event text,p_title text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n public.network_profiles; enabled boolean; BEGIN SELECT * INTO n FROM public.network_profiles WHERE user_id=p_user; enabled:=CASE p_event WHEN 'area' THEN coalesce(n.notify_area,true) WHEN 'interest' THEN coalesce(n.notify_interest,true) WHEN 'message' THEN coalesce(n.notify_message,true) WHEN 'connection' THEN coalesce(n.notify_connection,true) ELSE coalesce(n.notify_status,true) END; IF enabled THEN INSERT INTO public.network_notifications(user_id,referral_id,event,title) VALUES(p_user,p_ref,'realtor_network.'||p_event,p_title); END IF; END; $$;
CREATE FUNCTION public.network_members(p_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.network_eligible(auth.uid()) AND NOT public.is_admin() THEN RAISE EXCEPTION 'A Realtor license number on file is required'; END IF; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'first_name',p.first_name,'last_name',p.last_name,'avatar_url',p.avatar_url,'brokerage_name',p.brokerage_name,'markets',p.markets,'counties',p.counties,'services',p.services,'license_number',p.license_number,'license_state',p.license_state,'experience_history',p.experience_history,'cities',coalesce(n.cities,'{}'),'zip_codes',coalesce(n.zip_codes,'{}'),'primary_market',n.primary_market,'specialties',coalesce(n.specialties,'{}'),'credentials',n.credentials)) FROM public.profiles p LEFT JOIN public.network_profiles n ON n.user_id=p.id WHERE p.id=ANY(p_ids) AND p.role='realtor'),'[]'::jsonb); END; $$;
REVOKE ALL ON FUNCTION public.network_eligible(uuid),public.network_can_read(uuid),public.network_thread_access(uuid),public.network_area_match(uuid,text,text,text,text),public.network_notify(uuid,uuid,text,text),public.network_members(uuid[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.network_eligible(uuid),public.network_can_read(uuid),public.network_thread_access(uuid),public.network_members(uuid[]) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.network_area_match(uuid,text,text,text,text),public.network_notify(uuid,uuid,text,text) TO service_role;
COMMENT ON TABLE public.network_referrals IS 'Independent Realtor-to-Realtor network: never writes investor deals, matches, company referral agreements, commissions or legacy notifications.';